solution.python:
from typing import Optional

# TreeNode is supplied by the LeetCode judge.
class Solution:
    def maxDepth(self, root: Optional["TreeNode"]) -> int:
        if root is None:
            return 0
        return 1 + max(self.maxDepth(root.left), self.maxDepth(root.right))
